#!/usr/bin/env node
// Generates frontend/src/lib/attackTechniqueTactics.ts (technique -> tactic slugs)
// from a MITRE ATT&CK Enterprise STIX bundle. Usage:
//   node scripts/generate-attack-tactics.mjs <path-to-enterprise-attack-x.y.json>
// Bundles: github.com/mitre-attack/attack-stix-data (enterprise-attack/). Re-run
// when ATT&CK ships a new version and commit the generated file (not the bundle).
import { readFileSync, writeFileSync } from 'node:fs';
import { basename, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const input = process.argv[2];
if (!input) {
  console.error('usage: node scripts/generate-attack-tactics.mjs <enterprise-attack-x.y.json>');
  process.exit(1);
}
const out = join(dirname(fileURLToPath(import.meta.url)), '..', 'frontend/src/lib/attackTechniqueTactics.ts');

const bundle = JSON.parse(readFileSync(input, 'utf8'));
const version =
  basename(input).match(/enterprise-attack-(\d+(?:\.\d+)*)\.json$/)?.[1] ??
  bundle.objects.find((o) => o.type === 'x-mitre-collection')?.x_mitre_version ??
  'unknown';

const table = {};
for (const o of bundle.objects) {
  if (o.type !== 'attack-pattern' || o.revoked || o.x_mitre_deprecated) continue;
  const id = (o.external_references ?? []).find((r) => r.source_name === 'mitre-attack')?.external_id;
  if (!id || id.includes('.')) continue; // parent techniques only
  const tactics = (o.kill_chain_phases ?? [])
    .filter((p) => p.kill_chain_name === 'mitre-attack')
    .map((p) => p.phase_name);
  if (tactics.length) table[id] = [...new Set(tactics)].sort();
}

const ids = Object.keys(table).sort();
const body = ids.map((id) => `  ${id}: [${table[id].map((t) => `'${t}'`).join(', ')}],`).join('\n');
writeFileSync(
  out,
  `// GENERATED by scripts/generate-attack-tactics.mjs from MITRE ATT&CK Enterprise v${version}. Do not edit.
// Parent technique ID -> tactic slugs (match ENTERPRISE_TACTICS[].slug in mitreTactics.ts).
export const ATTACK_VERSION = '${version}';

export const TECHNIQUE_TACTICS: Record<string, readonly string[]> = {
${body}
};
`,
);
console.log(`ATT&CK v${version}: ${ids.length} techniques -> ${out}`);
